package android.graphics;
public class Typeface {public static final int NORMAL=0,BOLD=1;public static Typeface create(String name,int style){return new Typeface(new java.awt.Font(name,style,16));}public static Typeface create(Typeface base,int style){return new Typeface(base.font.deriveFont(style));}final java.awt.Font font;private Typeface(java.awt.Font f){font=f;}public static final Typeface DEFAULT_BOLD=new Typeface(new java.awt.Font(java.awt.Font.SANS_SERIF,java.awt.Font.BOLD,16));public static final Typeface MONOSPACE=new Typeface(new java.awt.Font(java.util.Arrays.asList(java.awt.GraphicsEnvironment.getLocalGraphicsEnvironment().getAvailableFontFamilyNames()).contains("Consolas")?"Consolas":java.awt.Font.MONOSPACED,0,16));public static Typeface createFromAsset(android.content.Context.Assets assets,String name){try(java.io.InputStream in=assets.open(name)){return new Typeface(java.awt.Font.createFont(java.awt.Font.TRUETYPE_FONT,in));}catch(Exception e){throw new IllegalArgumentException("Invalid font",e);}}public static Typeface createFromFile(java.io.File f){try{return new Typeface(java.awt.Font.createFont(java.awt.Font.TRUETYPE_FONT,f));}catch(Exception e){throw new IllegalArgumentException("Invalid font",e);}}}
